from pathlib import Path
import re

p = Path("src/components/TracksPlayer.jsx")
s = p.read_text()

# Remove temporary test text from earlier iterations.
s = s.replace('<div className="nyxtryp-auto-test">ПРИВЕТ</div>', '')
s = s.replace('ПРИВЕТ', '')

# Replace the complete L/R meter with the SVG construction used by the
# third reference (uchardon VU-Meter SVG/CSS animation): shallow curved
# scale, explicit SVG needle pivot and transform-origin style rotation.
marker = '          {!isMobile && (\n            <div className="tracks-mc-vu">'
start = s.find(marker)
if start < 0:
    raise SystemExit("L/R meter markup not found")
end = s.find('          )}', start)
if end < 0:
    raise SystemExit("L/R meter markup end not found")
end += len('          )}')

new_block = '''          {!isMobile && (\n            <div className="tracks-mc-vu">\n              {[['L', leftVU], ['R', rightVU]].map(([channel, value]) => {\n                const normalized = Math.max(0, Math.min(1, (value + 60) / 63))\n                const angle = -42 + normalized * 84\n\n                const ticks = Array.from({ length: 11 }, (_, i) => {\n                  const t = i / 10\n                  const x = 32 + 296 * t\n                  const y = 116 - 38 * (4 * t * (1 - t))\n                  const dx = 296\n                  const dy = -152 * (t - 0.5)\n                  const length = Math.hypot(dx, dy)\n                  const nx = -dy / length\n                  const ny = dx / length\n                  const major = i % 2 === 0\n                  const inner = major ? 5 : 3\n                  const outer = major ? 16 : 11\n                  return { i, x, y, nx, ny, inner, outer, major }\n                })\n\n                return (\n                  <div className="tracks-mc-meter" key={channel}>\n                    <div className="tracks-mc-window">\n                      <svg\n                        className="tracks-mc-gauge"\n                        viewBox="0 0 360 150"\n                        preserveAspectRatio="xMidYMid meet"\n                        aria-label={`${channel} analog VU meter`}\n                      >\n                        <defs>\n                          <linearGradient id={`mc-bg-${channel}`} x1="0" y1="0" x2="0" y2="1">\n                            <stop offset="0" stopColor="#a9e8f8" />\n                            <stop offset="0.52" stopColor="#53b9dc" />\n                            <stop offset="1" stopColor="#197da9" />\n                          </linearGradient>\n                          <radialGradient id={`mc-light-${channel}`} cx="50%" cy="58%" r="72%">\n                            <stop offset="0" stopColor="#ffffff" stopOpacity=".24" />\n                            <stop offset=".62" stopColor="#d8f7ff" stopOpacity=".06" />\n                            <stop offset="1" stopColor="#00141f" stopOpacity="0" />\n                          </radialGradient>\n                          <filter id={`mc-shadow-${channel}`} x="-30%" y="-30%" width="160%" height="160%">\n                            <feGaussianBlur stdDeviation="1.8" />\n                          </filter>\n                        </defs>\n\n                        <rect x="1" y="1" width="358" height="148" rx="3" fill="#03080c" stroke="#32434d" strokeWidth="2" />\n                        <rect x="7" y="7" width="346" height="136" rx="2" fill={`url(#mc-bg-${channel})`} />\n                        <rect x="7" y="7" width="346" height="136" rx="2" fill={`url(#mc-light-${channel})`} />\n\n                        <path d="M32 116 Q180 78 328 116" fill="none" stroke="rgba(4,32,47,.96)" strokeWidth="2.2" />\n                        <path d="M34 114 Q180 76 326 114" fill="none" stroke="rgba(235,252,255,.20)" strokeWidth="1" />\n\n                        {ticks.map(tick => (\n                          <g key={tick.i}>\n                            <line\n                              x1={tick.x + tick.nx * tick.inner}\n                              y1={tick.y + tick.ny * tick.inner}\n                              x2={tick.x + tick.nx * tick.outer}\n                              y2={tick.y + tick.ny * tick.outer}\n                              stroke="rgba(3,28,43,.96)"\n                              strokeWidth={tick.major ? 1.5 : 1}\n                            />\n                            {tick.major && (\n                              <text\n                                x={tick.x + tick.nx * 25}\n                                y={tick.y + tick.ny * 25 + 3}\n                                textAnchor="middle"\n                                fill="rgba(2,29,44,.96)"\n                                fontSize="8"\n                                fontFamily="Arial, sans-serif"\n                              >\n                                {[-20, -10, 0, 3, 6, 9][tick.i / 2]}\n                              </text>\n                            )}\n                          </g>\n                        ))}\n\n                        <text x="180" y="29" textAnchor="middle" fill="rgba(2,28,43,.96)" fontSize="9" fontWeight="700" fontFamily="Arial, sans-serif" letterSpacing="2.1">McINTOSH</text>\n                        <text x="180" y="40" textAnchor="middle" fill="rgba(2,28,43,.88)" fontSize="6.5" fontFamily="Arial, sans-serif" letterSpacing="1.1">STEREO POWER OUTPUT</text>\n                        <text x="180" y="136" textAnchor="middle" fill="rgba(2,28,43,.82)" fontSize="7" fontFamily="Arial, sans-serif" letterSpacing="1.4">{channel}</text>\n\n                        {/* The needle follows the reference's explicit pivot/origin idea. */}\n                        <line x1="180" y1="116" x2="180" y2="50" stroke="rgba(240,252,255,.38)" strokeWidth="4" strokeLinecap="round" filter={`url(#mc-shadow-${channel})`} />\n                        <g transform={`rotate(${angle} 180 116)`}>\n                          <line x1="180" y1="116" x2="180" y2="47" stroke="#f5fbff" strokeWidth="2.2" strokeLinecap="round" />\n                          <line x1="180" y1="116" x2="180" y2="53" stroke="#21465b" strokeWidth="0.8" strokeLinecap="round" />\n                        </g>\n                        <circle cx="180" cy="116" r="5" fill="#dcebf1" stroke="#163849" strokeWidth="1.5" />\n                        <circle cx="180" cy="116" r="1.5" fill="#06131a" />\n                      </svg>\n                    </div>\n                  </div>\n                )\n              })}\n            </div>\n          )}'''

s = s[:start] + new_block + s[end:]

# Replace only the custom meter CSS with dimensions suited to the SVG reference.
css_start = s.find('        .tracks-mc-vu {')
if css_start < 0:
    raise SystemExit("meter CSS start not found")
css_end = s.find('        @media (max-width: 600px) {', css_start)
if css_end < 0:
    raise SystemExit("meter CSS end not found")

new_css = '''        .tracks-mc-vu {\n          display: flex;\n          width: 100%;\n          gap: 14px;\n          justify-content: center;\n          align-items: stretch;\n          padding: 2px 0 4px;\n        }\n\n        .tracks-mc-meter {\n          flex: 1 1 0;\n          min-width: 0;\n        }\n\n        .tracks-mc-window {\n          width: 100%;\n          overflow: hidden;\n          border-radius: 3px;\n          background: #03080c;\n          border: 1px solid rgba(190,214,228,.42);\n          box-shadow: inset 0 0 0 1px rgba(0,0,0,.95), 0 5px 15px rgba(0,0,0,.28);\n        }\n\n        .tracks-mc-gauge {\n          width: 100%;\n          height: auto;\n          display: block;\n          aspect-ratio: 360 / 150;\n        }\n\n'''

s = s[:css_start] + new_css + s[css_end:]
p.write_text(s)
print("NYXTRYP: CodePen #3 SVG VU meter installed")